  #[using="Hsp Hva Hve Hfit BUDGET LENMAX KMAX BUD EXTRA_wf BUD_le GAP"] Theorem as0_main_entryU : forall ebs h, (h < 2)%nat -> forall E R FULL model, CSOK E (HSA h) R FULL model ->
    let A0 := as0_A0 EXTRA (HSA h) E in
