assert (G : exists can : word, rdn ASEGS MV (Z_to_bv 64 0x695ac0) 8 = Some (word_to_le_bytes 8 can)).
{ edestruct (ent_guard sp brk0 rdraw argv envp uid hw fs) as (can & G1 & G2); [ .. | exists can; exact G1]; eassumption. }
